<script lang="ts">
  import { onMount } from 'svelte';
  import type { FieldDefinition, JsonValue, SchemaResponse } from '../../api/domain';
  import { createField, loadSchema, loadStorageLayout, saveStorageLayout, updateField, updateSchemaOrder, updateSystemField } from '../../api/workspace';

  let schema = $state<SchemaResponse | null>(null); let loading = $state(true); let error = $state(''); let notice = $state('');
  let label = $state(''); let key = $state(''); let type = $state<FieldDefinition['field_type']>('text'); let required = $state(false); let unique = $state(false); let searchable = $state(true); let sortable = $state(true); let visible = $state(true); let priority = $state(50); let options = $state('');
  let autoScope = $state('global'); let autoPrefix = $state(''); let autoPadding = $state(0);
  let attachmentStorage = $state(''); let attachmentDescription = $state(''); let attachmentMultiple = $state(true); let attachmentMaxFiles = $state<number | undefined>(undefined);
  let folders = $state<string[]>([]); let storageCandidate = $state(''); let prefix = $state(''); let preview = $state(''); let frozen = $state(0);
  const activeFields = $derived(schema?.fields.filter((field) => field.active).sort((a, b) => a.position - b.position) || []);
  const storageFields = $derived(activeFields.filter((field) => field.field_type !== 'attachments'));

  onMount(() => void refresh());
  function generatedFieldKey() { return label.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').replace(/^[0-9]+/, '') || 'field'; }
  async function refresh() { loading = true; error = ''; try { schema = await loadSchema(true); const layout = await loadStorageLayout(); folders = layout.folder_fields.map((field) => field.uid); prefix = layout.file_prefix_field?.uid || ''; preview = layout.preview; frozen = layout.frozen_records; } catch (reason) { fail(reason); } finally { loading = false; } }
  function fail(reason: unknown) { error = reason instanceof Error ? reason.message : 'The operation failed.'; notice = ''; }
  function configFor(fieldType: string, currentOptions = ''): Record<string, JsonValue> { if (fieldType === 'select') return { options: currentOptions.split(',').map((v) => v.trim()).filter(Boolean) }; if (fieldType === 'attachments') { const maximum = Number(attachmentMaxFiles); return { storage_name: attachmentStorage || key || label, description: attachmentDescription, multiple: attachmentMultiple, max_files: attachmentMultiple && Number.isFinite(maximum) && maximum > 0 ? maximum : attachmentMultiple ? null : 1 }; } if (fieldType === 'auto_number') return { scope: autoScope, prefix: autoPrefix, padding: autoPadding }; return {}; }
  function syncType() { if (type === 'auto_number') { required = true; unique = true; sortable = true; } else if (type === 'attachments') { unique = false; searchable = true; sortable = false; } else if (type === 'long_text') sortable = false; else sortable = true; }
  async function add(event: SubmitEvent) { event.preventDefault(); loading = true; try { await createField({ label, key: key.trim().toLowerCase() || generatedFieldKey(), field_type: type, required: type === 'auto_number' ? true : required, unique_value: type === 'auto_number' ? true : type === 'attachments' ? false : unique, searchable, sortable: ['long_text', 'attachments'].includes(type) ? false : sortable, table_visible: visible, table_priority: priority, config: configFor(type, options) }); label = ''; key = ''; type = 'text'; options = ''; autoScope = 'global'; autoPrefix = ''; autoPadding = 0; attachmentStorage = ''; attachmentDescription = ''; attachmentMultiple = true; attachmentMaxFiles = undefined; required = false; unique = false; searchable = true; sortable = true; notice = 'Field created.'; await refresh(); } catch (reason) { fail(reason); } finally { loading = false; } }
  async function save(field: FieldDefinition) { try { await updateField(field.uid, { label: field.label, required: field.field_type === 'auto_number' ? true : field.required, unique_value: field.field_type === 'auto_number' ? true : field.field_type === 'attachments' ? false : field.unique_value, searchable: field.searchable, sortable: ['long_text', 'attachments'].includes(field.field_type) ? false : field.sortable, table_visible: field.table_visible, table_priority: field.table_priority, config: field.config }); notice = `${field.label} saved.`; await refresh(); } catch (reason) { fail(reason); } }
  async function toggle(field: FieldDefinition) { if (!confirm(`${field.active ? 'Archive' : 'Restore'} ${field.label}? Historical values are preserved.`)) return; try { await updateField(field.uid, { active: !field.active }); await refresh(); } catch (reason) { fail(reason); } }
  function schemaOrderFor(fieldUids: string[]) { if (!schema) return []; let fieldIndex = 0; return [...schema.system_fields.map((item) => ({ kind: 'system', id: item.key, position: item.position })), ...schema.fields.filter((item) => item.active).map((item) => ({ kind: 'field', id: item.uid, position: item.position }))].sort((a, b) => a.position - b.position).map((item) => item.kind === 'system' ? { kind: item.kind, id: item.id } : { kind: 'field', id: fieldUids[fieldIndex++] || item.id }); }
  async function saveOrder(fieldUids: string[]) { try { await updateSchemaOrder(schemaOrderFor(fieldUids)); await refresh(); notice = 'Field order saved.'; } catch (reason) { fail(reason); } }
  async function move(field: FieldDefinition, delta: number) { const ordered = [...activeFields]; const index = ordered.findIndex((item) => item.uid === field.uid); const target = index + delta; if (index < 0 || target < 0 || target >= ordered.length) return; [ordered[index], ordered[target]] = [ordered[target], ordered[index]]; await saveOrder(ordered.map((item) => item.uid)); }
  let draggedField = $state(''); let dragTargetField = $state('');
  function endFieldDrag() { draggedField = ''; dragTargetField = ''; }
  async function dropField(targetUid: string) { if (!draggedField || draggedField === targetUid) { endFieldDrag(); return; } const ordered = [...activeFields]; const from = ordered.findIndex((item) => item.uid === draggedField); const to = ordered.findIndex((item) => item.uid === targetUid); if (from < 0 || to < 0) { endFieldDrag(); return; } const [moved] = ordered.splice(from, 1); ordered.splice(to, 0, moved); endFieldDrag(); await saveOrder(ordered.map((item) => item.uid)); }
  async function saveSystem(keyName: string, visibleValue: boolean, priorityValue: number) { try { await updateSystemField(keyName, { table_visible: visibleValue, table_priority: priorityValue }); await refresh(); } catch (reason) { fail(reason); } }
  function fieldLabel(uid: string) { return activeFields.find((field) => field.uid === uid)?.label || 'Unavailable field'; }
  function addFolder() { if (!storageCandidate || folders.includes(storageCandidate)) return; folders = [...folders, storageCandidate]; storageCandidate = ''; }
  function moveFolder(index: number, delta: number) { const target = index + delta; if (target < 0 || target >= folders.length) return; const next = [...folders]; [next[index], next[target]] = [next[target], next[index]]; folders = next; }
  function removeFolder(index: number) { folders = folders.filter((_, item) => item !== index); }
  function stagedStoragePreview() { const parts = ['records', ...folders.map((uid) => `<${fieldLabel(uid)}>`), '<File Attachment field>']; const prefixField = activeFields.find((field) => field.uid === prefix); parts.push(prefixField ? `<${prefixField.label}>__filename.ext` : 'filename.ext'); return parts.join('/'); }
  async function saveLayout() { try { const result = await saveStorageLayout(folders, prefix || null); preview = result.preview; frozen = result.frozen_records; notice = 'Storage layout saved for future records.'; } catch (reason) { fail(reason); } }
</script>

{#if notice}<div class="notice success">{notice}</div>{/if}{#if error}<div class="notice error">{error}</div>{/if}
<div class="admin-grid">
  <section class="panel"><h2>Add record field</h2><form class="form-stack" onsubmit={add}><label>Label<input bind:value={label} required /></label><label>Key (optional override)<input bind:value={key} pattern="[a-z_][a-z0-9_]*" placeholder={`Generated: ${generatedFieldKey()}`} /></label><label>Type<select bind:value={type} onchange={syncType}><option value="text">Text</option><option value="long_text">Long text</option><option value="integer">Integer</option><option value="decimal">Decimal</option><option value="date">Date</option><option value="boolean">Boolean</option><option value="select">Select</option><option value="auto_number">Auto number</option><option value="attachments">File attachments</option></select></label>{#if type === 'select'}<label>Options (comma separated)<input bind:value={options} required /></label>{:else if type === 'auto_number'}<label>Sequence scope<select bind:value={autoScope}><option value="global">Global</option><option value="yearly">Reset yearly</option></select></label><label>Prefix<input bind:value={autoPrefix} /></label><label>Zero padding<input type="number" min="0" max="12" bind:value={autoPadding} /></label>{:else if type === 'attachments'}<label>Storage name<input bind:value={attachmentStorage} placeholder="Defaults to field label" /></label><label>Description<input bind:value={attachmentDescription} /></label><label class="checkbox"><input type="checkbox" bind:checked={attachmentMultiple} /> Allow multiple files</label><label>Maximum files<input type="number" min="1" max="10000" bind:value={attachmentMaxFiles} disabled={!attachmentMultiple} placeholder="Unlimited" /></label>{/if}<label>Table priority<input type="number" bind:value={priority} /></label><label class="checkbox"><input type="checkbox" bind:checked={required} disabled={type === 'auto_number'} /> Required</label><label class="checkbox"><input type="checkbox" bind:checked={unique} disabled={['attachments', 'auto_number'].includes(type)} /> Unique</label><label class="checkbox"><input type="checkbox" bind:checked={searchable} /> Searchable</label><label class="checkbox"><input type="checkbox" bind:checked={sortable} disabled={['long_text', 'attachments'].includes(type)} /> Sortable</label><label class="checkbox"><input type="checkbox" bind:checked={visible} /> Default table column</label><button class="button primary" disabled={loading}>Add field</button></form></section>
  <section class="panel admin-span"><div class="panel-heading"><div><h2>Record structure</h2><p class="muted">Fields drive the record table, editor, reports, and N1 storage.</p></div><span class="security-pill">Revision {schema?.revision || 0}</span></div>
    <div class="schema-list">{#if schema?.system_fields.length}<h3>System fields</h3>{#each schema.system_fields as field}<article class="schema-row"><div><strong>{field.label}</strong><small>{field.key} · {field.field_type}</small></div><label class="checkbox"><input type="checkbox" bind:checked={field.table_visible} /> Table</label><label>Priority<input class="short-input" type="number" bind:value={field.table_priority} /></label><button class="button small" onclick={() => saveSystem(field.key, field.table_visible, field.table_priority)}>Save</button></article>{/each}{/if}
      <div class="schema-section-heading"><h3>Custom fields</h3><small>Drag the grip to reorder active fields.</small></div>{#each schema?.fields || [] as field}<article class:dragging={draggedField === field.uid} class:drop-target={dragTargetField === field.uid && draggedField !== field.uid} ondragover={(event) => { if (field.active && draggedField) { event.preventDefault(); dragTargetField = field.uid; } }} ondragleave={(event) => { if (!event.currentTarget.contains(event.relatedTarget as Node | null) && dragTargetField === field.uid) dragTargetField = ''; }} ondrop={(event) => { event.preventDefault(); void dropField(field.uid); }} class:archived={!field.active} class="schema-card"><div class="schema-card-head"><div class="schema-field-title">{#if field.active}<button class="drag-handle" type="button" draggable="true" aria-label={`Drag ${field.label} to reorder`} title="Drag to reorder" ondragstart={(event) => { draggedField = field.uid; event.dataTransfer?.setData('text/plain', field.uid); }} ondragend={endFieldDrag}>⠿</button>{/if}<div><strong>{field.label}</strong><small>{field.key} · {field.field_type}{field.active ? '' : ' · archived'}</small></div></div><div class="inline-actions"><button class="button small" onclick={() => move(field, -1)} disabled={!field.active || activeFields[0]?.uid === field.uid}>↑</button><button class="button small" onclick={() => move(field, 1)} disabled={!field.active || activeFields[activeFields.length - 1]?.uid === field.uid}>↓</button><button class="button small" onclick={() => toggle(field)}>{field.active ? 'Archive' : 'Restore'}</button></div></div><div class="schema-edit"><label>Label<input bind:value={field.label} /></label><label>Priority<input type="number" bind:value={field.table_priority} /></label><label class="checkbox"><input type="checkbox" bind:checked={field.required} /> Required</label><label class="checkbox"><input type="checkbox" bind:checked={field.unique_value} disabled={['attachments', 'auto_number'].includes(field.field_type)} /> Unique</label><label class="checkbox"><input type="checkbox" bind:checked={field.searchable} /> Searchable</label><label class="checkbox"><input type="checkbox" bind:checked={field.sortable} disabled={['attachments', 'long_text'].includes(field.field_type)} /> Sortable</label><label class="checkbox"><input type="checkbox" bind:checked={field.table_visible} /> Default table column</label>{#if field.field_type === 'select'}<label class="full">Options<input value={(field.config.options as JsonValue[] || []).join(', ')} oninput={(event) => field.config = { options: event.currentTarget.value.split(',').map((v) => v.trim()).filter(Boolean) }} /></label>{:else if field.field_type === 'auto_number'}<label>Scope<select value={String(field.config.scope || 'global')} onchange={(event) => field.config = { ...field.config, scope: event.currentTarget.value }}><option value="global">Global</option><option value="yearly">Reset yearly</option></select></label><label>Prefix<input value={String(field.config.prefix || '')} oninput={(event) => field.config = { ...field.config, prefix: event.currentTarget.value }} /></label><label>Padding<input type="number" min="0" max="12" value={Number(field.config.padding || 0)} oninput={(event) => field.config = { ...field.config, padding: Number(event.currentTarget.value) }} /></label>{:else if field.field_type === 'attachments'}<label>Storage name<input value={String(field.config.storage_name || '')} oninput={(event) => field.config = { ...field.config, storage_name: event.currentTarget.value }} /></label><label>Description<input value={String(field.config.description || '')} oninput={(event) => field.config = { ...field.config, description: event.currentTarget.value }} /></label><label class="checkbox"><input type="checkbox" checked={field.config.multiple !== false} onchange={(event) => field.config = { ...field.config, multiple: event.currentTarget.checked }} /> Multiple files</label><label>Maximum files<input type="number" min="1" max="10000" value={String(field.config.max_files || '')} placeholder="Unlimited" oninput={(event) => { const raw = event.currentTarget.value; field.config = { ...field.config, max_files: raw ? Number(raw) : null }; }} /></label>{/if}<button class="button primary small" onclick={() => save(field)}>Save field</button></div></article>{/each}</div>
  </section>
  <section class="panel admin-wide"><div class="panel-heading"><div><h2>N1 storage layout</h2><p class="muted">Build the folder path in order. Existing {frozen} record folder{frozen === 1 ? '' : 's'} stay frozen; changes apply only to new records.</p></div><span class="security-pill">{folders.length} level{folders.length === 1 ? '' : 's'}</span></div><div class="storage-builder"><div><label>Add a folder level<select bind:value={storageCandidate}><option value="">Choose a record field…</option>{#each storageFields.filter((field) => !folders.includes(field.uid)) as field}<option value={field.uid}>{field.label}</option>{/each}</select></label><button class="button" type="button" onclick={addFolder} disabled={!storageCandidate}>Add level</button></div><ol class="storage-order">{#if !folders.length}<li class="storage-empty">Files will be stored directly inside each record folder.</li>{/if}{#each folders as uid, index}<li><span class="storage-index">{index + 1}</span><div><strong>{fieldLabel(uid)}</strong><small>Folder level {index + 1}</small></div><div class="inline-actions"><button class="button small" type="button" aria-label="Move up" onclick={() => moveFolder(index, -1)} disabled={index === 0}>↑</button><button class="button small" type="button" aria-label="Move down" onclick={() => moveFolder(index, 1)} disabled={index === folders.length - 1}>↓</button><button class="button small danger" type="button" onclick={() => removeFolder(index)}>Remove</button></div></li>{/each}</ol></div><div class="storage-options"><label>File-name prefix<select bind:value={prefix}><option value="">Keep the uploaded file name</option>{#each storageFields as field}<option value={field.uid}>Prefix with {field.label}</option>{/each}</select></label><div class="storage-preview"><span>New record path preview</span><code>{stagedStoragePreview()}</code>{#if preview}<small>Currently saved: {preview}</small>{/if}</div></div><div class="button-row"><button class="button primary" onclick={saveLayout}>Save storage layout</button></div></section>
</div>
